import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { simulationService } from '../../services/simulationService';
import { 
  Card, 
  Button, 
  Input, 
  StatusIndicator, 
  LoadingSpinner,
  Modal
} from '../../components';
import LoginForm from './components/LoginForm';
import ConfigurationPanel from './components/ConfigurationPanel';
import ErrorBoundary from '../../components/ErrorBoundary';
import './Simulation.styles.css';

const Simulation = () => {
  const navigate = useNavigate();
  const { isAuthenticated, authToken } = useAuth();

  const [simulationConfig, setSimulationConfig] = useState({
    cpe: '',
    startDate: '',
    endDate: '',
    timezone: 'local',
    outputFormat: 'xlsx'
  });

  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isSimulating, setIsSimulating] = useState(false);
  const [simulationStep, setSimulationStep] = useState('config');
  const [error, setError] = useState(null);
  const [simulationId, setSimulationId] = useState(null);

  useEffect(() => {
    // Set default dates to last month
    const now = new Date();
    const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const endOfLastMonth = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59);

    setSimulationConfig(prev => ({
      ...prev,
      startDate: lastMonth.toISOString().slice(0, 16),
      endDate: endOfLastMonth.toISOString().slice(0, 16)
    }));
  }, []);

  const handleConfigChange = (field, value) => {
    setError(null); // Clear errors when user makes changes
    setSimulationConfig(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const validateConfiguration = () => {
    const { cpe, startDate, endDate } = simulationConfig;

    if (!cpe.trim()) return 'CPE é obrigatório';
    if (!startDate) return 'Data de início é obrigatória';
    if (!endDate) return 'Data de fim é obrigatória';

    const start = new Date(startDate);
    const end = new Date(endDate);

    if (start >= end) return 'Data de início deve ser anterior à data de fim';

    // Validate CPE format (basic check)
    if (!cpe.match(/^PT\d{22}[A-Z]{2}$/)) {
      return 'Formato CPE inválido. Deve ser PT seguido de 22 dígitos e 2 letras.';
    }

    // Check if date range is not too large (performance)
    const daysDiff = (end - start) / (1000 * 60 * 60 * 24);
    if (daysDiff > 365) {
      return 'Período máximo permitido é de 365 dias.';
    }

    return null;
  };

  const handleStartSimulation = async () => {
    setError(null);

    const validationError = validateConfiguration();
    if (validationError) {
      setError(validationError);
      return;
    }

    if (!isAuthenticated) {
      setShowLoginModal(true);
      return;
    }

    await runSimulation();
  };

  const runSimulation = async () => {
    setIsSimulating(true);
    setSimulationStep('running');
    setError(null);

    try {
      // Create simulation request
      const simulationRequest = {
        ...simulationConfig,
        authToken,
        timestamp: new Date().toISOString()
      };

      // Call backend API - NO MOCK DATA
      const response = await simulationService.createSimulation(simulationRequest);

      if (!response.success) {
        throw new Error(response.error || 'Falha na criação da simulação');
      }

      const simId = response.simulationId;
      setSimulationId(simId);

      // Poll for results
      let attempts = 0;
      const maxAttempts = 60; // 5 minutes with 5-second intervals

      const pollResults = async () => {
        try {
          attempts++;
          const statusResponse = await simulationService.getSimulationStatus(simId);

          if (statusResponse.status === 'completed') {
            setSimulationStep('complete');

            // Redirect to results after short delay
            setTimeout(() => {
              navigate(`/results/${simId}`);
            }, 1500);

          } else if (statusResponse.status === 'failed') {
            throw new Error(statusResponse.error || 'A simulação falhou');

          } else if (statusResponse.status === 'running' && attempts < maxAttempts) {
            // Continue polling
            setTimeout(pollResults, 5000);

          } else if (attempts >= maxAttempts) {
            throw new Error('Timeout: A simulação está a demorar mais do que o esperado');
          }

        } catch (pollError) {
          console.error('Polling error:', pollError);
          throw pollError;
        }
      };

      // Start polling
      await pollResults();

    } catch (error) {
      console.error('Simulation failed:', error);
      setError(error.message || 'Erro desconhecido na simulação');
      setSimulationStep('config');
    } finally {
      setIsSimulating(false);
    }
  };

  const handleLoginSuccess = async () => {
    setShowLoginModal(false);
    // Wait a moment for auth state to update
    setTimeout(() => {
      runSimulation();
    }, 500);
  };

  if (error) {
    return (
      <ErrorBoundary error={error} onRetry={() => setError(null)}>
        <div className="simulation-error">
          <Card glass padding="xl" className="error-card">
            <div className="error-content">
              <div className="error-icon">❌</div>
              <h2>Erro na Simulação</h2>
              <p>{error}</p>
              <div className="error-actions">
                <Button 
                  variant="primary" 
                  onClick={() => {
                    setError(null);
                    setSimulationStep('config');
                  }}
                >
                  Tentar Novamente
                </Button>
                <Button 
                  variant="ghost" 
                  onClick={() => navigate('/')}
                >
                  Voltar ao Início
                </Button>
              </div>
            </div>
          </Card>
        </div>
      </ErrorBoundary>
    );
  }

  const getStepContent = () => {
    switch (simulationStep) {
      case 'config':
        return (
          <div className="simulation-grid">
            <ConfigurationPanel
              config={simulationConfig}
              onChange={handleConfigChange}
              onStart={handleStartSimulation}
              isAuthenticated={isAuthenticated}
              loading={isSimulating}
            />

            <Card glass className="auth-status-card">
              <div className="auth-status">
                <StatusIndicator
                  status={isAuthenticated ? 'success' : 'waiting'}
                  message={isAuthenticated 
                    ? 'Autenticado no Balcão Digital' 
                    : 'Autenticação necessária'
                  }
                />

                {isAuthenticated ? (
                  <div className="auth-details animate-fade-in">
                    <div className="auth-info">
                      <span className="auth-label">Status:</span>
                      <span className="auth-value">✅ Autenticado</span>
                    </div>
                    <div className="auth-info">
                      <span className="auth-label">Sessão:</span>
                      <span className="auth-value">Ativa</span>
                    </div>
                  </div>
                ) : (
                  <Button
                    variant="primary"
                    onClick={() => setShowLoginModal(true)}
                    className="login-button"
                  >
                    🔐 Fazer Login no Balcão Digital
                  </Button>
                )}
              </div>
            </Card>
          </div>
        );

      case 'running':
        return (
          <div className="simulation-running">
            <Card glass padding="xl" className="running-card">
              <div className="running-content">
                <LoadingSpinner size="lg" />
                <h2>Executando Simulação</h2>
                <p>A comunicar com o E-REDES para recolher os seus dados...</p>

                {simulationId && (
                  <div className="simulation-info">
                    <p className="simulation-id">ID: {simulationId}</p>
                  </div>
                )}

                <div className="progress-steps">
                  <div className="step completed">
                    <div className="step-icon">✅</div>
                    <div className="step-label">Configuração validada</div>
                  </div>
                  <div className="step active">
                    <div className="step-icon">🔄</div>
                    <div className="step-label">A recolher dados reais</div>
                  </div>
                  <div className="step">
                    <div className="step-icon">📊</div>
                    <div className="step-label">Processar resultados</div>
                  </div>
                </div>

                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => {
                    setSimulationStep('config');
                    setIsSimulating(false);
                  }}
                  className="cancel-button"
                >
                  Cancelar
                </Button>
              </div>
            </Card>
          </div>
        );

      case 'complete':
        return (
          <div className="simulation-complete">
            <Card glass padding="xl" className="complete-card">
              <div className="complete-content animate-fade-in">
                <div className="success-icon animate-bounce">🎉</div>
                <h2>Simulação Concluída!</h2>
                <p>Dados reais obtidos com sucesso. A redirecionionar...</p>
                <LoadingSpinner size="sm" />
              </div>
            </Card>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="simulation-page">
      <div className="page-header">
        <div className="header-content">
          <h1 className="page-title gradient-text">
            ⚡ Simulação de Consumo
          </h1>
          <p className="page-subtitle">
            Configure e execute a simulação da sua fatura com dados reais
          </p>
        </div>
      </div>

      <div className="simulation-content">
        {getStepContent()}
      </div>

      <Modal
        isOpen={showLoginModal}
        onClose={() => setShowLoginModal(false)}
        title="Autenticação E-REDES"
        size="lg"
      >
        <LoginForm 
          onSuccess={handleLoginSuccess}
          onCancel={() => setShowLoginModal(false)}
        />
      </Modal>
    </div>
  );
};

export default Simulation;
